(window.webpackJsonp=window.webpackJsonp||[]).push([[63],{438:function(v,_,n){"use strict";n.r(_);var r=n(5),b=Object(r.a)({},(function(){var v=this,_=v._self._c;return _("ContentSlotsDistributor",{attrs:{"slot-key":v.$parent.slotKey}},[_("p",[v._v("今日中秋西岐战事稍暇，众军士围坐在篝火旁吃吃喝喝好不快活，杨戬这日也未外出运粮，和小哪吒一起也找了处火堆与兵士们打成一片，乐呵呵谈天说地喝酒吃肉。"),_("br"),v._v("\n夜色渐深，月上枝头洒下一地银辉，小哪吒酒量不太行，端着酒碗正在发愁，又瞧见圆盘月影映在酒液里晃得人眼晕，忽而想起一事，皱皱眉头计上心来，叫一声“杨二哥”，借机撂了酒碗，才又说道：“嫦娥仙子送给你的贺礼大月饼，什么味道呢？”"),_("br"),v._v("\n众军士见势有八卦听！还是光风霁月二郎真君的八卦，霎时间也都不急着让酒了，或近或远都向这边竖起耳朵，却有一名西川来的士兵急了，拨开众人从后排一路抢上前：“杨少爷！哪吒先锋说的，可是真的？”"),_("br"),v._v("\n——当初遭水灾时他和家人可都是受过那位龙女娘娘的大恩惠，后来听说是治理天水拯救凡间的杨戬，也就是眼前这位二郎真君，和龙女娘娘西海三公主成了亲，他家虽然因为山高路远没赶上去吃喜酒，但自打他来了西岐军中，屡见杨将军手段，亦是认可了他们是一对郎才女貌情侣佳人。可要是……"),_("br"),v._v("\n——可要是姓杨这小子勾三搭四首尾不干净，那他就算是拼着以下犯上挨军棍，也是要拉他去武王和姜丞相面前说道说道的！")]),v._v(" "),_("p",[v._v("见这位军士满脸的愤愤不平，对面杨二郎却有些愣怔。"),_("br"),v._v("\n其实刚听得哪吒提起月饼杨戬就心下一沉，转念一想当时只顾着婚礼没来及问的，正好借机跟哪吒兄弟问个明白，却又没来及开口就被打了岔。"),_("br"),v._v("\n可他还没想明白，哪吒刚刚不是在问他问题吗？哪吒何曾说了什么？怎么就论起真不真来了呢？"),_("br"),v._v("\n但瞧着这位军士面上愤懑之色几变，眼瞅着就要变成失望和鄙夷了，容不得他更多细想，赶忙道：“这位大哥请放心，那月饼杨戬并没有吃。寸心也没吃。”"),_("br"),v._v("\n他不是很确切地知道要请人放什么心，就这么脱口而出了，但好像确实让这位军士大哥放下心来，立时神色就和缓了不少。"),_("br"),v._v("\n杨戬忙又斟一碗酒敬上，补问一句：“这位大哥，如何称呼？”"),_("br"),v._v("\n那军士接了酒碗一饮而尽——行军之人间这就算解了误会了——又通姓名，再道出身籍贯。"),_("br"),v._v("\n一时旁边亦有人匀出了座位，让军士大哥就坐。此时又有人道：“这么说，既然咱杨将军君子无意，那就只能是那位蟾宫仙子神女有梦咯？”"),_("br"),v._v("\n杨戬忽地恍然大悟，原来刚刚那位西川的军士大哥问的是他和嫦娥有没有什么苟且，原来大哥是在给寸心打抱不平哩！杨戬虽面上不显，禁不住已经在心里击节赞叹了——真好呀，果不愧是龙女娘娘结下的善缘！"),_("br"),v._v("\n于是对这位大哥愈发刮目相看，杨戬默默记下对方姓名，又连敬三碗。")]),v._v(" "),_("p",[v._v("转眼却见他哪吒兄弟垂着头，脸色红一阵白一阵的。"),_("br"),v._v("\n哪吒刚刚听到杨戬说月饼没吃时回忆起来，他杨二哥婚礼当场宾主尽欢，确实没见到也没人提过那块月饼，他正隐隐约约好像要抓住什么头绪了，忽听得那句振聋发聩般的“君子无意神女有梦”，刹那都串了起来。"),_("br"),v._v("\n再想到为着这扶周伐纣的大业，他连他杨二哥的洞房都没闹上，吃完喜酒就早早随父亲回家打点行装。后在西岐再见时却听哮天犬说他二哥二嫂的洞房花烛夜过得煞是与众不同，杨戬是在凉亭里睡了一夜，第二天临走新娘子都没出来送送他。"),_("br"),v._v("\n不由得愤愤道：“兄弟思虑不周带了个祸胎，连累嫂子因这月饼跟你吵架，是兄弟错了。”"),_("br"),v._v("\n旁边有人惊讶：“这里面还有事儿？”原来不仅仅是有人送个贺礼吗？"),_("br"),v._v("\n杨戬也奇道：“哪吒兄弟这话可从何说起？”"),_("br"),v._v("\n小哪吒于是一五一十把那仙子是怎么在南天门外拦住他，要他代为转送贺礼，把她只说月饼是“给他”的，是他还自以为是懂事圆滑、替人着想，帮她圆成了“给你们”，全都和盘托出，末了说：“我对不起二哥二嫂。”"),_("br"),v._v("\n旁边起哄架秧子者众，有说“先锋官，这事确是你办得不对了”的，有说“这招叫借刀杀人，咱们战阵上也有用过”的，有为小哪吒说话的，说“哪吒先锋还是年纪太轻，所以不知人心险恶”，或者“利用小孩子，什么人啊”，有爱扣细节的，“都已经在南天门外了，先锋官说得对呀，喝杯茶的功夫，她怎么自己不去？”旁边就有人来解答了，“嗨呀，那不就是因为送的东西讨嫌才不去的嘛，亲自去的话不就给人把她连人带东西扔出去的机会了嘛”，亦有沉浸式分析行为动机的，“总之更加确定是这位仙子单方面倒贴了”、“别人都成亲了她还不死心，这种死皮赖脸的我也是见过的，我们村……”，说什么的都有。"),_("br"),v._v("\n有单纯者道“适逢八月十五，就不能是单纯应个节庆吗？月饼代表团团圆圆的呀”，则立马有辩驳的声音“杨将军家的情况你不知道吗？你懂不懂忌讳啊？这种日子里这种事，只得他自家能讲，别人是万万提不得的，不然跟当着和尚的面儿骂秃子，又有什么分别？”"),_("br"),v._v("\n军士们讲话粗糙直来直去，理却是天然的。这些话杨戬听着不知不觉解开了许多疑惑，也释怀了并不是他自己思虑过甚太把人往坏处想。但小哪吒听在耳朵里却是越来越懊恼不已。"),_("br"),v._v("\n原来是他被人利用给二哥二嫂带去了麻烦，刚刚他还想拿这个打趣他二哥。他杨二哥是宽宏大量，可他自己岂能因为别人不计较就轻易原谅自己？小哪吒腾地起立：“我就该半路把那破月饼丢掉！”"),_("br"),v._v("\n杨戬忙放下酒碗安慰他：“这不怪你。”"),_("br"),v._v("\n哪吒和军士们不知那月饼底细，以为扔了就可万事大吉，他们的好意他心领了，可比起无知无觉地被人暗中针对，他觉得还是这样有所知觉要更好一些，至少他可以提前防备着。"),_("br"),v._v("\n杨戬反复告诉哪吒“你二哥和二嫂都没有怪过你”，好容易安抚住结义兄弟，连他自己说过的“不打女人”都搬出来了，哪吒几次坐下又站起，如此几番挣扎，到最后坐下时还咬牙切齿：“不打女人，我哪吒不打女人……”")]),v._v(" "),_("p",[v._v("终于安抚住哪吒，众人也渐渐歇了声息，杨戬缓缓舒了口气。"),_("br"),v._v("\n其实那天他从哪吒手中接过月饼起，他就直觉那月饼有问题了。捱到夜深人静独自揭开盒盖是果不其然的来者不善，但也更是出乎意料的诛心谶语——那位仙子不是号称是母亲的老相识吗？那位仙子不是母亲故事里的大英雄后羿的爱妻吗？可自从他认识她以来，以他所见，她做过和没做过的事情，不仅不像英雄后羿那般值得人感激和崇拜，至见到月饼的这一刻疑惑更加深重了，就算她是要向他示警告诉他天廷绝不会对他和寸心的婚姻袖手旁观，可难道就非要用他母亲的殒身之难来点醒吗？"),_("br"),v._v("\n他是不敢相信，更是不能认谶，所以只拿新婚贺礼和中秋节物这样不会出错的说辞搪塞。刚刚不知是哪位大哥说的，他说寸心是敏锐的，他说得对，寸心一眼就看穿了，寸心说这个月饼根本就不是送给她的，寸心说这个月饼仅仅是送给他一个人的。"),_("br"),v._v("\n寸心更说得对。"),_("br"),v._v("\n杨戬又抿了一口酒，咽下去时有些涩喉。"),_("br"),v._v("\n刚刚还有一位大哥对他说：“你老婆吃醋闹你了？嗨呀那你就偷着乐吧！她吃醋说明她心里有你，说明她爱你呀。你可要好好珍惜。”"),_("br"),v._v("\n这位大哥说得也对。")]),v._v(" "),_("p",[v._v("他当时是怎么想的？怎么会问出“明天成婚还成不成了”这样的话？是因为明明她早上还开心着要做他的媳妇儿了，晚上却似乎想反悔吗？是他太害怕了吗？是他太害怕失去她了吗？"),_("br"),v._v("\n杨戬忽而很难压抑自己的嘴角。"),_("br"),v._v("\n原来，寸心不是生气，也不是反悔，原来她是在为他吃醋吗？")]),v._v(" "),_("p",[v._v("他想她了。"),_("br"),v._v("\n他更想她了。")]),v._v(" "),_("p",[v._v("夜色愈深篝火熄了大半，军士们也纷纷回帐休息。"),_("br"),v._v("\n夜色中一棵树下仿佛有金光一闪，若是再想定睛细看，却又觉得刚刚定是自己看花了眼。"),_("br"),v._v("\n与此同时几千里外的灌江口杨府，亦是金光微闪，夜色中闪现出一道着了甲的身影。")]),v._v(" "),_("p",[v._v("正房主卧暗着灯，杨戬照例先去他们的婚床上坐了一会儿，大红的婚帐都还没撤下，颜色依然艳丽夺目——一别七年，他真的好想她——杨戬轻轻抚摸着红纱，忍着满腔的思念思索：寸心会不会、有没有，偶尔也想一想他呢？"),_("br"),v._v("\n他不在家的日子里寸心和三妹姑嫂两个小姑娘总腻在一处，吃在一处睡在一处，夜深了他不便打扰，于是每次偷偷回来也只能像这样在空荡荡的婚房里坐上一会儿，好在房间里还有些寸心活动过的痕迹，就比如现在梳妆台上摊开着的贝壳小盒，想必是白天寸心刚刚把玩过，看来她今日白天确是想过他的？"),_("br"),v._v("\n还有寸心吃剩下的小小半块月饼，杨戬拿起来嗅了嗅，味道甜甜的，馅儿是枣泥。"),_("br"),v._v("\n放下月饼时忽然听得轻轻的水声，从浴室那边传来的。杨戬一时不敢相信自己的耳朵，小心翼翼地走过去，屏住呼吸静静聆听，他的心越来越狂跳不止，水声也愈发清晰。")]),v._v(" "),_("p",[v._v("浴室中水雾里，寸心无聊地甩甩尾巴正打算起身不想那冤家了，忽而听见门栓响动的声音，回过头就见刚刚想念里的人推开了门。")]),v._v(" "),_("p",[v._v("可是，她还光着呢。")]),v._v(" "),_("p",[v._v("差点儿掀翻屋顶的尖叫声中杨戬狼狈转身，可眼前的美人玉体已挥之不去，再一时才想起来寸心早已经是他的妻子了，他慌什么？他躲什么呢？"),_("br"),v._v("\n冷静下来的龙女也开始反省，除去本该在西岐前线的人怎么半夜回到了家里，好像赶他出去，亦没道理？"),_("br"),v._v("\n门扇再响，那人挟着秋夜的风又卷了进来，三两步路之间丢盔弃甲一气呵成，扑进水里游到她身边抱住她扣住她手臂和后脑，深深地吻了下去。")]),v._v(" "),_("p",[v._v("杨戬感受着他身下的小龙女，起初还有些僵硬，渐渐地放软身段，再渐渐地手臂抬起来勾住他脖颈，亲吻也从单方面的接受开始变得更加热烈更加主动，长长一吻结束稍事休息，两个人都醉眼迷离。"),_("br"),v._v("\n两两相望身子还紧紧贴在一起。"),_("br"),v._v("\n下一步该做什么了呢？")]),v._v(" "),_("p",[v._v("杨戬打横抱起小龙女，他抱着他的妻子，也不管水珠滴滴答答洇了一路痕迹，一路上岸走出浴室走过书房，走进他们的婚帐里。打个响指燃起红烛，今夜便是那一夜的继续。"),_("br"),v._v("\n杨戬埋入龙女胸口将那双峰软肉先都含吃了一遍，不住口地唤她的名字诉说别后离情，小龙女听着一声声温柔缱绻柔情蜜语，挺着一对儿晶莹红艳挺翘朱果，在他大掌下一阵阵酸软了腰肢，整个人被他圈在怀里，他的手渐渐向着她腿心游移，她想：七年了，他们终于要完成他们的洞房花烛，合卺之礼。")]),v._v(" "),_("p",[v._v("他终于要挺入之前她说。"),_("br"),v._v("\n“轻点儿。”"),_("br"),v._v("\n他回答。"),_("br"),v._v("\n“嗯。”"),_("br"),v._v("\n可待他真正抵上去时她还是闭上眼睛还微微发起颤来。"),_("br"),v._v("\n于是他又说：“寸心，你上来。”")]),v._v(" "),_("p",[v._v("小龙女睁开眼睛，还不知道她要“上”哪里去。杨戬已经先扶了她起来，然后自己在床中央坐稳，然后又扶了她坐到他身上去。"),_("br"),v._v("\n“寸心自己控制着，轻一点儿、重一点儿，都可以。”"),_("br"),v._v("\n寸心觉得自己脸颊烫得厉害，想必看在他眼里一定红透了吧。可他在下面也不老实，又顶又蹭地勾引她……"),_("br"),v._v("\n心一横，这都送到嘴边了，自己的男人，没有不吃的道理。")]),v._v(" "),_("p",[v._v("于是狠狠坐下去。")]),v._v(" "),_("p",[v._v("小龙女娇喘嘤咛，杨二郎也忍不住闷哼出声。"),_("br"),v._v("\n小龙女从前不知道被填补的感觉竟是如此圆满下意识地缠上他绞住他想要更亲密。杨二郎亦再证了书上得来终是浅，只有自己真正地深入了解才晓得是如何地销魂蚀骨，流连难返，才晓得“乾坤交感阴阳相合”八个字里蕴着何等深厚丰富的奥秘。")]),v._v(" "),_("p",[v._v("终于捱过第一轮的刺激。寸心稍得了喘息这才有空低下头去看，但见杨戬抬着头目光灼灼紧紧盯住她，想到刚刚自己的一举一动怕是都被他这样一眼不错地看得干净，女儿家的羞怯一时间翻涌上来，连绣满如意团纹的婚帐都仿佛灼人眼底。寸心抬起手来挥灭蜡烛，却不妨黑暗里失了视觉却让嗅觉和触觉更加清晰。"),_("br"),v._v("\n“寸心、寸心。”——是杨戬贴上来吻她的下巴和唇角。"),_("br"),v._v("\n“寸心，寸心……”——是杨戬按紧她腰肢，肉杵在她小腹深处重重碾过去。"),_("br"),v._v("\n“寸心……”“啊——！”——是他连连冲刺后定在高点把最灼热的精华注入进了她的身体！"),_("br"),v._v("\n他毛茸茸的脑袋埋在她颈窝里，深重的喘息响在她耳边，她忽而只想紧紧地抱抱他，轻轻地亲亲他。杨戬感受到自己被龙女温柔拢住头颈，缱绻的吻落在他的发顶，这双轻柔的小手就这样抚慰住了他的不安他的焦虑，轻而易举。")]),v._v(" "),_("p",[v._v("趁热打铁再接再厉。龙女体娇两趟下来已是气喘吁吁，软软挂在杨二郎肩膀上又哭又笑，小拳头捶着他胸口小尖牙尝着他血肉：“你怎么才回来、才回来呀！”"),_("br"),v._v("\n杨戬微有愣怔但马上明了这不是真要他自辩的时候，按下向她诉说自己从前屡屡扑空的失落委屈，只保证：“以后杨戬有空就回，有空就多会回来，定把龙女娘娘伺候得舒舒服服，不让我的寸心独守空房。”"),_("br"),v._v("\n又轮到小龙女替他担心：“那西岐前线也离不开你，莫耽误了军务，师叔那里你不好交代……”"),_("br"),v._v("\n杨戬立刻攫住小龙女两片弱软的唇瓣他现在并不想听这些。继而翻身起来将小龙女躺平放好，再把双臂勾在她腿弯里免了她用力，然后他整个人覆了上去。")]),v._v(" "),_("p",[v._v("上上下下忽高忽低，不知几番乾坤几轮阴阳，窗外夜色渐浅，远远似传来鸡鸣鸟啼。"),_("br"),v._v("\n寸心又累又困眼皮不住打架，却还有一桩事放心不下，趁着这一轮的间隙又软绵绵推他胸口软绵绵催促：“二郎莫为我耽误了军务……”"),_("br"),v._v("\n杨戬咬咬牙，下面又连顶十几下顶得小龙女连连娇呼完，这才恨恨抽出来，把人抱去胡乱洗过再抱回来裹好被子，然后又亲了亲她，才道：“等寸心睡着了，我就回去。”")]),v._v(" "),_("p",[v._v("坐在床边牵着她的手，听着小龙女呼吸声渐轻，看着她颈侧胸口如梅花点点绽放的痕迹，杨戬开始微微有些反思，她是真的被自己折腾狠了？那他下次试试，尽量收着点儿力。")]),v._v(" "),_("p",[v._v("忽而有些腹中饥，杨戬视线落到妆台上寸心剩下的半块枣泥月饼上，摄过来拿在手上细细端详，咬一口甜香在舌尖上绽开在口腔里爆满，再低头去看他的小龙女，这一刻的幸福无以复加无可比拟。"),_("br"),v._v("\n不过忽又觉得，寸心哪里像那些军士们说的那样敏锐，她都保护不好她自己，她可有想过——杨戬指尖抚上寸心锁骨上一处吻痕——他若是就这样一走了之，若是她这个样子被人看见，她有没有想过……"),_("br"),v._v("\n有没有想过龌龊者能编出什么样的流言蜚语？"),_("br"),v._v("\n杨戬不由得手上稍加了几分力，应是攥得紧了惹得龙女娘娘皱起眉头，他醒过神来忙又松开手，连亲带哄。终于哄得龙女又睡熟了，外面天色几乎大亮，也有女子脚步声向后院来。")]),v._v(" "),_("p",[v._v("三圣母看到开门出来的人是她亲哥，倒也无丝毫讶异。"),_("br"),v._v("\n她往他身后紧闭的门扉上又看了几眼，问：“嫂子她……”"),_("br"),v._v("\n杨戬心内甚嚣尘上：“对，是我！都是我！都怪我！是我折腾她累了！”"),_("br"),v._v("\n说出口的却只得轻描淡写两个字：“是我。”仿佛仅仅是在说“三妹你没认错确实是你二哥我回来了”。"),_("br"),v._v("\n杨婵见他顶盔贯甲披挂得齐整，又问：“二哥，你不跟嫂子告个别再走吗？”"),_("br"),v._v("\n杨戬回过头又往屋里瞧了好一会儿，梅开二度：“不了，让她多睡一会儿吧。”"),_("br"),v._v("\n连叮嘱也要再重复一次：“三妹，辛苦你了。二哥不在家的时候，你嫂子，就托付给你了。”")]),v._v(" "),_("p",[v._v("不过这一次目送他飞去西岐的，真真地只得他三妹一个人了，而已。")])])}),[],!1,null,null,null);_.default=b.exports}}]);